/**
 * Whaleal Cart 安装页 — 输入店铺域名后跳转 OAuth（Whaleal Cart 授权）
 * @author 恒哥
 */
import React, { useState } from 'react';
import Layout from '../components/Layout';
import SEO from '../components/SEO';
import {
  PRODUCT_NAME,
  PRODUCT_NAME_FULL,
  SHOPIFY_APP_STORE_URL,
  SHOPIFY_APP_STORE_LABEL,
  SHOPIFY_APP_URL,
  buildOAuthInstallUrl,
  normalizeShopDomain,
} from '../constants/brand';
import './page.css';

export default function InstallPage() {
  const [shopInput, setShopInput] = useState('');
  const [error, setError] = useState('');

  const handleSubmit = (event) => {
    event.preventDefault();
    const shop = normalizeShopDomain(shopInput);
    if (!shop) {
      setError('Enter a valid Shopify store, e.g. my-store or my-store.myshopify.com');
      return;
    }
    const url = buildOAuthInstallUrl(shop);
    if (typeof window !== 'undefined') {
      window.location.href = url;
    }
  };

  return (
    <Layout>
      <SEO
        title={`Install ${PRODUCT_NAME}`}
        description={`Install ${PRODUCT_NAME_FULL} on your Shopify store. Enter your shop domain to authorize Whaleal Cart.`}
        pathname="/install"
      />
      <div className="page-container about-page">
        <div className="page-header about-header">
          <h1>Install {PRODUCT_NAME}</h1>
          <p>Connect your Shopify store to {PRODUCT_NAME_FULL}</p>
        </div>

        <div className="about-content">
          <section className="about-section">
            <h2>Connect your store</h2>
            <p>
              Enter your Shopify store domain below. You will be redirected to Shopify to approve{' '}
              <strong>{PRODUCT_NAME}</strong> — not a third-party listing.
            </p>

            <form
              onSubmit={handleSubmit}
              style={{
                maxWidth: '480px',
                marginTop: '24px',
                padding: '24px',
                background: '#f9fafb',
                borderRadius: '8px',
                border: '1px solid #e5e7eb',
              }}
            >
              <label htmlFor="shop-domain" style={{ display: 'block', fontWeight: 600, marginBottom: '8px' }}>
                Shopify store domain
              </label>
              <div style={{ display: 'flex', gap: '12px', flexWrap: 'wrap' }}>
                <input
                  id="shop-domain"
                  type="text"
                  name="shop"
                  autoComplete="off"
                  placeholder="my-store.myshopify.com"
                  value={shopInput}
                  onChange={(e) => {
                    setShopInput(e.target.value);
                    setError('');
                  }}
                  style={{
                    flex: '1 1 220px',
                    padding: '12px 14px',
                    fontSize: '16px',
                    border: '1px solid #d1d5db',
                    borderRadius: '6px',
                  }}
                />
                <button
                  type="submit"
                  className="homepage-button homepage-button-primary"
                  style={{ padding: '12px 20px', border: 'none', cursor: 'pointer' }}
                >
                  Install {PRODUCT_NAME}
                </button>
              </div>
              {error && (
                <p style={{ color: '#b91c1c', marginTop: '12px', marginBottom: 0, fontSize: '14px' }}>
                  {error}
                </p>
              )}
              <p style={{ marginTop: '16px', marginBottom: 0, fontSize: '14px', color: '#6b7280' }}>
                Example: <code>dev-whale.myshopify.com</code> or just <code>dev-whale</code>
              </p>
            </form>
          </section>

          <section className="about-section">
            <h2>What happens next?</h2>
            <ol>
              <li>Shopify opens the OAuth consent screen for <strong>{PRODUCT_NAME}</strong></li>
              <li>Review permissions (checkouts, customers, discounts, orders)</li>
              <li>After approval, you land in the embedded app at {new URL(SHOPIFY_APP_URL).host}</li>
            </ol>
            <p style={{ marginTop: '16px' }}>
              Prefer the App Store? When listed, you can also install from{' '}
              <a href={SHOPIFY_APP_STORE_URL} target="_blank" rel="noopener noreferrer" className="about-link">
                {PRODUCT_NAME} on {SHOPIFY_APP_STORE_LABEL}
              </a>
              .
            </p>
          </section>
        </div>
      </div>
    </Layout>
  );
}
